// Semantic-version precedence and range checking (pure string comparisons).
//
// A version is MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]. Each numeric component
// is a nonnegative integer with no leading zero. PRERELEASE and BUILD are
// dot-separated nonempty identifiers of ASCII alphanumerics and "-". A purely
// numeric prerelease identifier must not have a leading zero.
//
// Precedence (SemVer-style):
//   - major, then minor, then patch compared numerically
//   - build metadata is ignored entirely
//   - a version WITH a prerelease ranks BELOW the same version without one
//   - prerelease identifiers compared left to right; numeric ids compare
//     numerically, non-numeric ids compare by ASCII order, numeric < non-numeric,
//     and (all else equal) the shorter list ranks lower
import path from 'node:path';
import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

const PATTERN =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$/;
const IDENT = /^[0-9A-Za-z-]+$/;
const OPERATOR = /^(>=|<=|=|>|<)?(.+)$/;

// Parse a version string into its structural parts. Throws on invalid input.
// Build metadata is captured (for validation) but never used in precedence.
function parse(v) {
  if (typeof v !== 'string') throw new Error('invalid version');
  const m = PATTERN.exec(v);
  if (!m) throw new Error('invalid version');
  let prerelease = [];
  if (m[4] !== undefined) {
    prerelease = m[4].split('.');
    for (const id of prerelease) {
      if (!IDENT.test(id)) throw new Error('invalid version');
      // purely numeric identifiers must not have a leading zero ("0" is fine)
      if (/^\d+$/.test(id) && id.length > 1 && id[0] === '0') {
        throw new Error('invalid version');
      }
    }
  }
  let build = [];
  if (m[5] !== undefined) {
    build = m[5].split('.');
    for (const id of build) {
      if (!IDENT.test(id)) throw new Error('invalid version');
    }
  }
  return { major: +m[1], minor: +m[2], patch: +m[3], prerelease, build };
}

// Compare two prerelease identifier lists (each nonempty).
function comparePrerelease(left, right) {
  const n = Math.min(left.length, right.length);
  for (let i = 0; i < n; i++) {
    const d = compareIdentifier(left[i], right[i]);
    if (d !== 0) return d;
  }
  if (left.length === right.length) return 0;
  return left.length < right.length ? -1 : 1;
}

function compareIdentifier(a, b) {
  const isNum = (s) => /^\d+$/.test(s);
  const aN = isNum(a);
  const bN = isNum(b);
  if (aN && bN) {
    if (a === b) return 0;
    return BigInt(a) < BigInt(b) ? -1 : 1;
  }
  if (aN) return -1; // numeric always below non-numeric
  if (bN) return 1;
  if (a === b) return 0;
  return a < b ? -1 : 1; // ASCII order for non-numeric
}

// Compare two parsed versions by precedence.
function compareParsed(x, y) {
  for (const k of ['major', 'minor', 'patch']) {
    if (x[k] !== y[k]) return x[k] < y[k] ? -1 : 1;
  }
  const hasL = x.prerelease.length > 0;
  const hasR = y.prerelease.length > 0;
  if (hasL !== hasR) return hasL ? -1 : 1; // prerelease < release
  if (!hasL) return 0;
  return comparePrerelease(x.prerelease, y.prerelease);
}

export function compareVersions(a, b) {
  return compareParsed(parse(a), parse(b));
}

// Parse a range into clauses of comparators. Throws on invalid ranges.
// Each comparator is {op, parsed}; op is one of =,<,<=,>,>=.
function parseRange(range) {
  if (typeof range !== 'string' || range.length === 0) {
    throw new Error('invalid range');
  }
  const clauses = [];
  for (const raw of range.split('||')) {
    const tokens = raw.trim().split(/\s+/).filter(Boolean);
    if (tokens.length === 0) throw new Error('invalid range: empty clause');
    const comparators = [];
    for (const tok of tokens) {
      const m = OPERATOR.exec(tok);
      if (!m) throw new Error('invalid range: bad comparator');
      comparators.push({ op: m[1] ?? '=', parsed: parse(m[2]) });
    }
    clauses.push(comparators);
  }
  return clauses;
}

const key = (v) => v.major + '.' + v.minor + '.' + v.patch;

// Does `version` satisfy `range`? Throws on invalid version or range.
export function satisfies(version, range) {
  const x = parse(version);
  const clauses = parseRange(range);
  const hasPre = x.prerelease.length > 0;
  for (const comparators of clauses) {
    let ok = true;
    for (const { op, parsed: y } of comparators) {
      const d = compareParsed(x, y);
      const pass =
        op === '=' ? d === 0 :
        op === '>' ? d > 0 :
        op === '>=' ? d >= 0 :
        op === '<' ? d < 0 :
        d <= 0;
      if (!pass) { ok = false; break; }
    }
    if (!ok) continue;
    // A prerelease version only satisfies a clause when some comparator in
    // that clause also carries a prerelease with the same major.minor.patch.
    if (hasPre) {
      const k = key(x);
      let matched = false;
      for (const { parsed: y } of comparators) {
        if (y.prerelease.length > 0 && key(y) === k) { matched = true; break; }
      }
      if (!matched) continue;
    }
    return true;
  }
  return false;
}

// ---------------------------------------------------------------------------
// CLI: node semver-range.js INPUT_JSON_FILE
// ---------------------------------------------------------------------------

class CliError extends Error {}

function runCli(args) {
  if (args.length !== 1) {
    throw new CliError('usage: node semver-range.js INPUT_JSON_FILE');
  }
  const inputPath = args[0];
  let data;
  try {
    data = JSON.parse(readFileSync(inputPath, 'utf8'));
  } catch (err) {
    throw new CliError('cannot read/parse input file: ' + err.message);
  }
  if (data === null || typeof data !== 'object' || Array.isArray(data)) {
    throw new CliError('input must be a non-null, non-array object');
  }
  const versions = data.versions;
  if (
    !Array.isArray(versions) ||
    versions.some((v) => typeof v !== 'string')
  ) {
    throw new CliError('versions must be a dense array of version strings');
  }
  // Validate the range on every invocation, even when there are no versions.
  parseRange(data.range);
  const parsed = versions.map((v) => [v, parse(v)]);
  // Stable sort keeps input order among equal versions.
  parsed.sort((a, b) => compareParsed(a[1], b[1]));
  const sorted = parsed.map((p) => p[0]);
  const satisfying = sorted.filter((v) => satisfies(v, data.range));
  process.stdout.write(JSON.stringify({ sorted, satisfying }) + '\n');
}

// Only run the CLI when this module is the program entry point, so importing
// it never triggers CLI behaviour.
let isMain = false;
try {
  const entry =
    typeof process.argv[1] === 'string'
      ? pathToFileURL(path.resolve(process.argv[1])).href
      : '';
  isMain = entry !== '' && entry === import.meta.url;
} catch {
  isMain = false;
}

if (isMain) {
  try {
    runCli(process.argv.slice(2));
  } catch (err) {
    process.exitCode = 2;
    process.stderr.write(
      (err && err.message ? err.message : 'error') + '\n'
    );
  }
}

