+    throw new Error('invalid range');
+  }
+  const clauses = [];
+  for (const raw of range.split('||')) {
+    const tokens = raw.trim().split(/\s+/).filter(Boolean);
+    if (tokens.length === 0) throw new Error('invalid range: empty clause');
+    const comparators = [];
+    for (const tok of tokens) {
